import json,math
from pathlib import Path
r=Path('artifacts');b=json.loads((r/'airport-relocation-baseline.json').read_text(encoding='utf-8'));a=json.loads((r/'airport-relocation-airspace.json').read_text(encoding='utf-8'));terrain=json.loads((r/'airport-relocation-site-terrain.json').read_text(encoding='utf-8'));box={'min_x':1132,'max_x':2268,'min_z':-1988,'max_z':-1612};tiles=b['tiles']['items']
def owned(x,z):return any(t['bounds']['min_x']<=x<=t['bounds']['max_x'] and t['bounds']['min_z']<=z<=t['bounds']['max_z'] for t in tiles)
