svg=['<svg id="map" viewBox="-600 -200 4200 3200" role="img" aria-label="东西向机场及两端净空规划"><rect x="-8000" y="-8000" width="16000" height="16000" fill="#e9edf1"/>']
for t in tiles:
 q=t['bounds'];svg.append(f'<rect x="{q["min_x"]}" y="{-q["max_z"]}" width="{q["max_x"]-q["min_x"]}" height="{q["max_z"]-q["min_z"]}" fill="#edf2e7" stroke="#c8d4c1" stroke-width="5"/>')
