for x,y,t in [(2500,1210,'新建立交预留'),(1700,1510,'航站楼前路'),(2800,2090,'东端净空'),(400,2090,'西端净空'),(400,300,'旧城住宅'),(6200,-2700,'八角城镇'),(6800,-1900,'原机场场址：停用规划')]:svg.append(f'<text x="{x}" y="{y}" font-size="42" fill="#203d46" stroke="#f5f7f0" stroke-width="8" paint-order="stroke">{t}</text>')
